package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class SubmissionApiTest {
 StudyApiTest f;SubmissionStore store;SubmissionController api;UUID study,assignment;
 @BeforeEach void setup(){f=new StudyApiTest();f.setup();var ids=new UuidV7(Clock.systemUTC());study=ids.next();assignment=ids.next();store=mock(SubmissionStore.class);api=new SubmissionController(store,f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String body){var r=f.req(method,body);r.removeHeader("If-Match");r.addHeader("If-Match","\"su0\"");return r;}
 String body(){return "{\"content\":\"Answer\",\"assignmentVersion\":2}";}
 SubmissionStore.Submission value(){return new SubmissionStore.Submission(f.id,assignment,study,f.group,f.space,f.actor,1,2,"Answer","AUTHOR_AND_OWNER",Instant.now().toString(),Instant.now().toString());}
 @Test void memberAndOwnerSubmitOnlyAuthenticatedActorAndReplayStatus()throws Exception{
  var v=value();when(store.submit(eq(f.group),eq(f.space),eq(study),eq(assignment),eq(f.actor),eq(0L),eq(2L),eq("a".repeat(32)),eq("Answer"),anyString())).thenReturn(new SubmissionStore.Result(v,true),new SubmissionStore.Result(v,false));f.role("MEMBER");var first=api.submit(f.group.toString(),study.toString(),assignment.toString(),req("POST",body()));f.role("OWNER");var retry=api.submit(f.group.toString(),study.toString(),assignment.toString(),req("POST",body()));assertEquals(201,first.getStatusCode().value());assertEquals(200,retry.getStatusCode().value());assertEquals("\"su1\"",first.getHeaders().getETag());assertEquals("no-store",first.getHeaders().getCacheControl());assertTrue(first.getHeaders().getLocation().toString().endsWith("/submissions/"+f.id));
 }
 @Test void viewerReadsOwnHistoryButCannotSubmitOrEnumerateOthers()throws Exception{
  f.role("VIEWER");when(store.mine(f.group,f.space,study,assignment,f.actor,false)).thenReturn(new SubmissionStore.Mine(null,false));var mine=api.mine(f.group.toString(),study.toString(),assignment.toString(),req("GET",null));assertEquals("\"su0\"",mine.getHeaders().getETag());assertEquals(403,assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),req("POST",body()))).getStatusCode().value());assertEquals(403,assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),assignment.toString(),req("GET",null))).getStatusCode().value());api.history(f.group.toString(),study.toString(),assignment.toString(),f.id.toString(),req("GET",null));verify(store).history(f.group,f.space,study,assignment,f.id,f.actor,false,Long.MAX_VALUE,5);
 }
 @Test void ownerCatalogDoesNotRequireWriteOriginAndMemberReadIsAuthorScoped()throws Exception{
  var read=req("GET",null);read.removeHeader("Origin");assertEquals(200,api.list(f.group.toString(),study.toString(),assignment.toString(),read).getStatusCode().value());f.role("MEMBER");when(store.get(f.group,f.space,study,assignment,f.id,f.actor,false)).thenReturn(value());api.get(f.group.toString(),study.toString(),assignment.toString(),f.id.toString(),req("GET",null));verify(store).get(f.group,f.space,study,assignment,f.id,f.actor,false);assertThrows(ResponseStatusException.class,()->api.list(f.group.toString(),study.toString(),assignment.toString(),req("GET",null)));
 }
 @Test void strictContentKeysPreconditionsAndQueriesRejectSpoofing(){
  for(String b:List.of("{}",body()+" {}","{\"content\":\"A\",\"content\":\"B\",\"assignmentVersion\":2}",body().replace("Answer",""),body().replace("2}","2.0}"),body().replace("2}","0}"),body().replace("2}","9223372036854775808}"),body().replace("2}","2,\"authorId\":\"spoof\"}"),body().replace("Answer","\\u0000"),body().replace("Answer","\\ud800")))assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),req("POST",b)));
  var missing=req("POST",body());missing.removeHeader("If-Match");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),missing)).getStatusCode().value());for(String tag:List.of("*","W/\"su0\"","\"as1\"","\"su01\"","\"su9999999999999999999\"")){var v=req("POST",body());v.removeHeader("If-Match");v.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),v));}var key=req("POST",body());key.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),key));var query=req("GET",null);query.addParameter("authorId",f.actor.toString());assertThrows(ResponseStatusException.class,()->api.mine(f.group.toString(),study.toString(),assignment.toString(),query));verifyNoInteractions(store);
 }
 @Test void credentialOriginAndMembershipDenialsPrecedePersistence(){
  var bad=req("POST",body());bad.setSecure(false);var duplicate=req("POST",body());duplicate.addHeader("Cookie","__Host-brain_guest="+f.token);var origin=req("POST",body());origin.addHeader("Origin","https://elsewhere.example");for(var v:List.of(bad,duplicate,origin))assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),v));verifyNoInteractions(f.auth,store);when(f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.actor,"REGISTERED",List.of()));assertThrows(ResponseStatusException.class,()->api.mine(f.group.toString(),study.toString(),assignment.toString(),req("GET",null)));verifyNoInteractions(store);
 }
 @Test void byteBoundsAndReadBodiesStayStrict(){var large=req("POST","x".repeat(65537));assertEquals(413,assertThrows(ResponseStatusException.class,()->api.submit(f.group.toString(),study.toString(),assignment.toString(),large)).getStatusCode().value());assertThrows(ResponseStatusException.class,()->api.mine(f.group.toString(),study.toString(),assignment.toString(),req("GET","{}")));assertThrows(ResponseStatusException.class,()->SubmissionInput.validate("한".repeat(10923),2));assertDoesNotThrow(()->SubmissionInput.validate("x".repeat(32768),2));verifyNoInteractions(store);}
}
